                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      drop policy if exists "Users can remove their own video bookmarks" on public.video_bookmarks;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      create policy "Users can remove their own video bookmarks"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      on public.video_bookmarks for delete to authenticated
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      using (user_id = (select auth.uid()));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      grant select, insert, delete on table public.video_bookmarks to authenticated;
alter table public.videos
  add column if not exists thumbnail_url text,
  add column if not exists thumbnail_path text;
